UPDATE corridor.vehicle_sightings AS v
SET position = ST_LineInterpolatePoint(n.geom, ST_LineLocatePoint(s.geom, v.position))
FROM (
    SELECT x.sighting_id, COALESCE(
        (SELECT ne.segment_id
         FROM events.enforcement_recommendations AS r
         JOIN _veer_osm_segments AS ne ON ne.segment_id::TEXT = r.evidence->>'segment_id'
         WHERE r.sighting_id = x.sighting_id
         ORDER BY r.created_at, r.recommendation_id
         LIMIT 1),
        (SELECT g.segment_id
         FROM corridor.road_segments AS g
         JOIN _veer_osm_segments AS ng ON ng.segment_id = g.segment_id
         WHERE g.geom && ST_Expand(x.position, 0.0001)
           AND ST_DWithin(g.geom::geography, x.position::geography, 0.5)
         ORDER BY g.segment_id IS DISTINCT FROM c.segment_id,
                  ST_Distance(g.geom::geography, x.position::geography), g.segment_id
         LIMIT 1),
        c.segment_id) AS segment_id
    FROM corridor.vehicle_sightings AS x
    LEFT JOIN corridor.cameras AS c ON c.camera_id = x.camera_id
    WHERE x.source = 'emulated_anpr'
) AS a
JOIN corridor.road_segments AS s ON s.segment_id = a.segment_id
JOIN _veer_osm_segments AS n ON n.segment_id = a.segment_id
WHERE v.sighting_id = a.sighting_id
  AND v.source = 'emulated_anpr'
  AND NOT ST_OrderingEquals(s.geom, n.geom);

-- ... and the same reads in the runs' recorded tapes (emulator.emulation_runs:
-- the God's-eye REPLAY draws a tape's reads, a server-side replay re-posts
-- them as duplicates of the stored ones).  An anpr_read frame whose read_id
-- is the sighting id of an EMULATED read of the same camera takes that read's
-- position (7 decimals, ~1 cm).  Only payload.position changes — every other
-- frame, field and column is kept — and a frame already within 5 cm of its
-- read is left alone, so a second apply (or a store whose tapes already
-- match its reads) changes nothing.  A tape without reads is not rewritten.
UPDATE emulator.emulation_runs AS r
SET tape = jsonb_set(r.tape, '{frames}', m.frames)
FROM (
    SELECT t.run_id,
           jsonb_agg(CASE WHEN s.sighting_id IS NULL THEN f.frame
                          ELSE jsonb_set(f.frame, '{payload,position}',
                                         jsonb_build_array(round(ST_X(s.position)::NUMERIC, 7),
                                                           round(ST_Y(s.position)::NUMERIC, 7)))
                     END ORDER BY f.ord) AS frames,
           count(s.sighting_id) AS moved
    FROM emulator.emulation_runs AS t
    CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(t.tape->'frames') = 'array'
                                                 THEN t.tape->'frames' END)
                       WITH ORDINALITY AS f (frame, ord)
    CROSS JOIN LATERAL (
        SELECT CASE WHEN f.frame->>'kind' = 'anpr_read'
                     AND jsonb_typeof(f.frame->'payload'->'position'->0) = 'number'
                     AND jsonb_typeof(f.frame->'payload'->'position'->1) = 'number'
                    THEN ST_SetSRID(ST_MakePoint((f.frame->'payload'->'position'->>0)::FLOAT8,
                                                 (f.frame->'payload'->'position'->>1)::FLOAT8), 4326)
               END AS position
    ) AS tp
    LEFT JOIN corridor.vehicle_sightings AS s
      ON tp.position IS NOT NULL
     AND s.sighting_id::TEXT = f.frame->'payload'->>'read_id'
     AND s.camera_id = f.frame->'payload'->>'camera_id'
     AND s.source = 'emulated_anpr'
     AND NOT ST_DWithin(s.position::geography, tp.position::geography, 0.05)
    WHERE t.tape @? '$.frames[*] ? (@.kind == "anpr_read")'
    GROUP BY t.run_id
) AS m
WHERE r.run_id = m.run_id
  AND m.moved > 0;

-- =============================================================================
-- A. SEGMENTS
-- =============================================================================

INSERT INTO corridor.road_segments AS s (segment_id, road_name, road_class, lanes,
    speed_limit_kmh, oneway, geom, osm_way_id, geom_source, geom_meta)
SELECT segment_id, road_name, road_class, lanes, speed_limit_kmh, oneway, geom,
    osm_way_id, 'osm', geom_meta
FROM _veer_osm_segments
ON CONFLICT (segment_id) DO UPDATE SET
    road_name = EXCLUDED.road_name, road_class = EXCLUDED.road_class,
    lanes = EXCLUDED.lanes, speed_limit_kmh = EXCLUDED.speed_limit_kmh,
    oneway = EXCLUDED.oneway, geom = EXCLUDED.geom, osm_way_id = EXCLUDED.osm_way_id,
    geom_source = EXCLUDED.geom_source, geom_meta = EXCLUDED.geom_meta,
    display_geom = NULL, display_geom_source = NULL, display_geom_meta = NULL,
    updated_at = NOW()
WHERE s.road_name IS DISTINCT FROM EXCLUDED.road_name
   OR s.road_class IS DISTINCT FROM EXCLUDED.road_class
   OR s.lanes IS DISTINCT FROM EXCLUDED.lanes
   OR s.speed_limit_kmh IS DISTINCT FROM EXCLUDED.speed_limit_kmh
   OR s.oneway IS DISTINCT FROM EXCLUDED.oneway
   OR NOT ST_OrderingEquals(s.geom, EXCLUDED.geom)
   OR s.osm_way_id IS DISTINCT FROM EXCLUDED.osm_way_id
   OR s.geom_source IS DISTINCT FROM EXCLUDED.geom_source
   OR s.geom_meta IS DISTINCT FROM EXCLUDED.geom_meta
   OR s.display_geom IS NOT NULL OR s.display_geom_source IS NOT NULL
   OR s.display_geom_meta IS NOT NULL;

-- =============================================================================
-- B. JUNCTIONS (explicit ids; the serial continues after the highest)
-- =============================================================================

