DELETE FROM corridor.segment_adjacency sa
WHERE NOT EXISTS (
    SELECT 1 FROM _veer_osm_moves m
    WHERE m.from_segment_id = sa.from_segment_id
      AND m.to_segment_id = sa.to_segment_id
      AND m.via_junction_id = sa.via_junction_id
);

INSERT INTO corridor.segment_adjacency AS sa (from_segment_id, to_segment_id,
    via_junction_id, turn_cost_sec)
SELECT from_segment_id, to_segment_id, via_junction_id, turn_cost_sec FROM _veer_osm_moves
ON CONFLICT (from_segment_id, to_segment_id, via_junction_id) DO UPDATE SET
    turn_cost_sec = EXCLUDED.turn_cost_sec
WHERE sa.turn_cost_sec IS DISTINCT FROM EXCLUDED.turn_cost_sec;

