-- =============================================================================
-- G. PROVENANCE — the original seed wrote random numbers into the REAL-only
-- traffic.hourly_aggregates (migration 019), stamped date_trunc('hour', NOW())
-- of the seed load, which is also every seeded segment's created_at.  Only
-- that hour bucket is touched (the bucket starting within the hour before the
-- seed load, whatever the seed session's time zone), and a row survives when
-- a data_quality = 'real' observation of its segment exists in its hour.
-- =============================================================================

DELETE FROM traffic.hourly_aggregates h
WHERE h.hour_utc <= (SELECT min(created_at) FROM corridor.road_segments)
  AND h.hour_utc > (SELECT min(created_at) FROM corridor.road_segments) - interval '1 hour'
  AND NOT EXISTS (
      SELECT 1 FROM traffic.observations o
      WHERE o.segment_id = h.segment_id
        AND o.data_quality = 'real'
        AND o.timestamp_utc >= h.hour_utc
        AND o.timestamp_utc < h.hour_utc + interval '1 hour'
  );

-- =============================================================================
-- H. EVENT-PROFILE SPINES — events.event_profiles holds each use case's
-- representative route (migrations 008 / 010), drawn on the schematic
-- network: most are no longer paths on the real one.  A profile whose spine
-- is STILL the seeded value takes the route the use-case library runs on this
-- network (services/event-emulator/src/event_emulator/use_case_library.json,
-- which scripts/scenario_library.json agrees with) — every one a legal
-- directed path, the one-ways included (the generator checks).  A spine an
-- operator changed is kept.  Events already instantiated from a profile
-- (events.event_routes) are recorded history and are not rewritten.
-- Profiles already on their library route are not listed.
-- =============================================================================

UPDATE events.event_profiles AS p
SET route_segment_ids = v.spine
FROM (VALUES
    ('kumbh_scale_gathering', ARRAY[1001, 1006, 1010]::BIGINT[], ARRAY[1001, 1006, 1009]::BIGINT[]),
    ('metro_work_zone', ARRAY[1031, 1014, 1024]::BIGINT[], ARRAY[1031, 1014, 1049, 1038]::BIGINT[]),
    ('motera_stadium_egress', ARRAY[1032, 1002, 1001]::BIGINT[], ARRAY[1032, 1041, 1009, 1002, 1001]::BIGINT[]),
    ('national_day_parade', ARRAY[1028, 1027, 1024, 1025]::BIGINT[], ARRAY[1029, 1028, 1048, 1024, 1025]::BIGINT[]),
    ('rath_yatra_ahmedabad', ARRAY[1012, 1015, 1005, 1013]::BIGINT[], ARRAY[1012, 1049, 1013]::BIGINT[]),
    ('riverfront_marathon', ARRAY[1007, 1001, 1006, 1010]::BIGINT[], ARRAY[1007, 1015, 1001, 1006]::BIGINT[]),
    ('vvip_convoy_base', ARRAY[1026, 1025, 1024, 1014, 1030]::BIGINT[], ARRAY[1026, 1025, 1024, 1048, 1028, 1027, 1043]::BIGINT[]),
    ('watchlist_anpr_sweep', ARRAY[1012, 1015, 1005, 1013]::BIGINT[], ARRAY[1015, 1012, 1049, 1013]::BIGINT[])
) AS v (profile_id, seeded, spine)
WHERE p.profile_id = v.profile_id
  AND p.route_segment_ids = v.seeded
  AND p.route_segment_ids IS DISTINCT FROM v.spine;

-- =============================================================================
-- I. EVENT-PROFILE TEXT — a profile column still at the value its migration
-- seeded, where that value promises what the emulator does not do, takes the
-- honest text: the watchlist sweep (010) promised an EARMARKED-plate hit, but
-- GJ27EM4321 is an operator exercise — the emulator never earmarks it, its reads
-- hit only after a duty officer has (the use-case library's wording, expected
-- feature operator_earmark_exercise).  Data hygiene: nothing reads these
-- columns at run time.  A column an operator changed is kept, and a second
-- apply changes nothing.
-- =============================================================================

UPDATE events.event_profiles AS p
SET description = v.corrected
FROM (VALUES
    ('watchlist_anpr_sweep',
     'A stolen-vehicle report drives an emulated ANPR camera sweep along the '
     'old-city belt. Deterministic camera reads include the stolen plate and an '
     'earmarked plate (both clearly labelled emulated) plus patrolling Jan '
     'Rakshak units. Sightings land in corridor.vehicle_sightings with source '
     'emulated_anpr and drive deterministic e-challan recommendations that only a '
     'human officer can approve.',
     'EMULATED watchlist scenario (clearly labelled, never a live feed). A '
     'stolen-vehicle FIR drives an ANPR camera sweep around the walled city. '
     'Deterministic camera reads cover background traffic, the FIR-named stolen '
     'plate GJ27EM9001 and the earmark-exercise plate GJ27EM4321, plus patrolling '
     'Jan Rakshak units. The FIR is the premise of the scenario, stated at t0 as '
     'a labelled EMULATED precondition (a stolen_vehicle_fir earmark on '
     'GJ27EM9001), so the reads of the stolen car hit as stolen_vehicle and file '
     'evidence-only R_STOLEN_SIGHTING recommendations, never a fine. GJ27EM4321 '
     'is an OPERATOR EXERCISE: the emulator never earmarks it, so its reads hit '
     'as earmarked_plate only after a duty officer has earmarked it with a lawful '
     'basis. Sightings land in corridor.vehicle_sightings with source '
     'emulated_anpr, the oracle computes every hit and rule, and only a named '
     'human officer acts on any recommendation.')
) AS v (profile_id, seeded, corrected)
WHERE p.profile_id = v.profile_id
  AND p.description = v.seeded
  AND p.description IS DISTINCT FROM v.corrected;

UPDATE events.event_profiles AS p
SET template = v.corrected
FROM (VALUES
    ('watchlist_anpr_sweep',
     '{"n_cameras": 4, "n_background_vehicles": 6, "stolen_plate_hit": true, '
     '"earmarked_plate_hit": true, "n_agency_units": 2, "seed": 20261105}'::jsonb,
     '{"n_cameras": 4, "n_background_vehicles": 6, "stolen_plate_hit": true, '
     '"earmarked_plate_hit": false, "n_agency_units": 2, "seed": 20261105, '
     '"operator_earmark_exercise": true}'::jsonb)
) AS v (profile_id, seeded, corrected)
WHERE p.profile_id = v.profile_id
  AND p.template = v.seeded
  AND p.template IS DISTINCT FROM v.corrected;

COMMIT;
